import {createInterface} from 'node:readline';
import {dirname,join} from 'node:path';
import {DatabaseSync} from 'node:sqlite';
import {startInstance} from '../../dist/instance-service.js';
const [path,port]=process.argv.slice(2);let receive;
const slackTransport={verifyDestination:async(_tokens,config)=>({channelId:config.channelId}),identify:async()=>({teamId:'T123',botUserId:'B123'}),start:async(_tokens,handler,status)=>{receive=handler;status?.('connected');return ()=>{receive=undefined}},post:async(_tokens,message)=>{process.stdout.write('POST '+JSON.stringify(message)+'\n');}};
const providerFactory=async()=>({name:'fixture',capabilities:{toolCalls:false,incrementalText:false},complete:async()=>({role:'assistant',content:'Browser fixture reply'})});
const app=startInstance(path,Number(port),{env:{},slackTransport,providerFactory});await app.listen();
process.stdout.write('Pairing code: '+app.code+'\n');
createInterface({input:process.stdin}).on('line',line=>{if(line==='event' && receive)void receive({eventId:'EvBrowser',teamId:'T123',userId:'U123',channelId:'D123',text:'Hello from browser fixture'});if(line==='interrupted-setup'){const db=new DatabaseSync(join(dirname(path),'secrets','credentials.sqlite'));try{db.prepare("INSERT INTO credential_transition_pending VALUES ('slack','synthetic-interrupted')").run();}finally{db.close();}process.stdout.write('INTERRUPTED\n');}});
process.on('SIGTERM',()=>{void app.close().then(()=>process.exit(0));});
